const fs = require('fs');

function main() {
    const parts = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (parts.length >= 2) {
        const a = parseInt(parts[0], 10);
        const b = parseInt(parts[1], 10);
        console.log(a > b ? a : b);
    }
}

main();
